==== dates.ts
     1	const ISO_DATE = /^(\d{4})-(\d{2})-(\d{2})$/;
     2	
     3	export const WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
     4	
     5	const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
     6	
     7	/** Formats a screening as `<Weekday> <D> <Mon> <HH:mm>`, e.g. `Tuesday 15 Sep 16:00`. */
     8	export function formatShowDate(isoDate: string, time: string): string {
     9	  const date = parseIsoDate(isoDate);
    10	  if (!date) {
    11	    return `${isoDate} ${time}`;
    12	  }
    13	  return `${WEEKDAYS[date.getDay()]} ${date.getDate()} ${MONTHS[date.getMonth()]} ${time}`;
    14	}
    15	
    16	/** Formats a date as `YYYY-MM-DD` in the browser's local time zone. */
    17	export function toIsoDate(date: Date): string {
    18	  const month = String(date.getMonth() + 1).padStart(2, '0');
    19	  const day = String(date.getDate()).padStart(2, '0');
    20	  return `${date.getFullYear()}-${month}-${day}`;
    21	}
    22	
    23	/** Parses a `YYYY-MM-DD` string into a local date, or returns `null` if it is not a real calendar date. */
    24	export function parseIsoDate(value: string | null | undefined): Date | null {
    25	  const match = value ? ISO_DATE.exec(value) : null;
    26	  if (!match) {
    27	    return null;
    28	  }
    29	  const year = Number(match[1]);
    30	  const month = Number(match[2]);
    31	  const day = Number(match[3]);
    32	  const date = new Date(year, month - 1, day);
    33	  const valid = date.getFullYear() === year && date.getMonth() === month - 1 && date.getDate() === day;
    34	  return valid ? date : null;
    35	}
==== booking.ts
     1	import { Injectable, inject, signal } from '@angular/core';
     2	import { CanActivateFn, Router } from '@angular/router';
     3	
     4	/**
     5	 * One selectable element of the auditorium as booked: a single seat, or a couch that
     6	 * covers `column` and `column + 1`.
     7	 */
     8	export interface BookedItem {
     9	  row: number;
    10	  column: number;
    11	  couch: boolean;
    12	}
    13	
    14	/** The values typed into the checkout form (spec 7). */
    15	export interface CheckoutValues {
    16	  firstName: string;
    17	  lastName: string;
    18	  email: string;
    19	  confirmEmail: string;
    20	  phone: string;
    21	  terms: boolean;
    22	}
    23	
    24	/** The booking in progress, kept in `sessionStorage` (spec 3.1). */
    25	export interface Booking {
    26	  screeningId: number;
    27	  /** Selected seats and couches, in row then column order. */
    28	  items: BookedItem[];
    29	  form: CheckoutValues;
    30	  /** The customer's email once the booking is paid; `null` while it is in progress. */
    31	  paidEmail: string | null;
    32	}
    33	
    34	const STORAGE_KEY = 'cinescope.booking';
    35	
    36	/** A checkout form with nothing typed in. */
    37	export function emptyCheckoutValues(): CheckoutValues {
    38	  return { firstName: '', lastName: '', email: '', confirmEmail: '', phone: '', terms: false };
    39	}
    40	
    41	/** Identifiers of the seats an element occupies; a couch contributes both of its seats. */
    42	export function seatIdentifiers(item: BookedItem): string[] {
    43	  const columns = item.couch ? [item.column, item.column + 1] : [item.column];
    44	  return columns.map((column) => `R${item.row}C${column}`);
    45	}
    46	
    47	/** Price of one element in PLN (spec 5.4). A couch is priced as a whole. */
    48	export function priceOf(item: BookedItem): number {
    49	  if (item.couch) {
    50	    return 89;
    51	  }
    52	  if (item.row <= 5) {
    53	    return 25;
    54	  }
    55	  if (item.row <= 10) {
    56	    return 32;
    57	  }
    58	  return 39;
    59	}
    60	
    61	/** Total price of the items in PLN. */
    62	export function totalPrice(items: readonly BookedItem[]): number {
    63	  return items.reduce((sum, item) => sum + priceOf(item), 0);
    64	}
    65	
    66	/** Formats an amount as `25.00 PLN`. */
    67	export function formatPrice(amount: number): string {
    68	  return `${amount.toFixed(2)} PLN`;
    69	}
    70	
    71	/** Identifies a booked element; the same key the seat map uses for its elements. */
    72	export function itemKey(item: BookedItem): string {
    73	  return `${item.couch ? 'couch' : 'seat'}-${item.row}-${item.column}`;
    74	}
    75	
    76	function sortItems(items: readonly BookedItem[]): BookedItem[] {
    77	  return [...items].sort((a, b) => a.row - b.row || a.column - b.column);
    78	}
    79	
    80	function readStoredBooking(): Booking | null {
    81	  try {
    82	    const raw = sessionStorage.getItem(STORAGE_KEY);
    83	    if (!raw) {
    84	      return null;
    85	    }
    86	    const stored = JSON.parse(raw) as Booking;
    87	    return {
    88	      ...stored,
    89	      form: { ...emptyCheckoutValues(), ...stored.form },
    90	      paidEmail: stored.paidEmail ?? null,
    91	    };
    92	  } catch {
    93	    return null;
    94	  }
    95	}
    96	
    97	/** Holds the booking in progress and mirrors it into `sessionStorage`. */
    98	@Injectable({ providedIn: 'root' })
    99	export class BookingStore {
   100	  private readonly state = signal<Booking | null>(readStoredBooking());
   101	
   102	  /** The booking in progress, or `null`. */
   103	  readonly booking = this.state.asReadonly();
   104	
   105	  /**
   106	   * Keeps the booking in progress when it belongs to the screening and is unpaid; otherwise
   107	   * starts an empty one.
   108	   */
   109	  open(screeningId: number): void {
   110	    const current = this.state();
   111	    if (current?.screeningId !== screeningId || current.paidEmail !== null) {
   112	      this.write({ screeningId, items: [], form: emptyCheckoutValues(), paidEmail: null });
   113	    }
   114	  }
   115	
   116	  /** Replaces the selected items of the booking in progress. */
   117	  setItems(items: readonly BookedItem[]): void {
   118	    const current = this.state();
   119	    if (current) {
   120	      this.write({ ...current, items: sortItems(items) });
   121	    }
   122	  }
   123	
   124	  /** Sets one value of the checkout form in the booking in progress. */
   125	  updateForm<K extends keyof CheckoutValues>(field: K, value: CheckoutValues[K]): void {
   126	    const current = this.state();
   127	    if (current) {
   128	      this.write({ ...current, form: { ...current.form, [field]: value } });
   129	    }
   130	  }
   131	
   132	  /** Marks the booking in progress as paid by the customer with this email address. */
   133	  markPaid(email: string): void {
   134	    const current = this.state();
   135	    if (current) {
   136	      this.write({ ...current, paidEmail: email });
   137	    }
   138	  }
   139	
   140	  clear(): void {
   141	    this.write(null);
   142	  }
   143	
   144	  private write(booking: Booking | null): void {
   145	    this.state.set(booking);
   146	    if (booking) {
   147	      sessionStorage.setItem(STORAGE_KEY, JSON.stringify(booking));
   148	    } else {
   149	      sessionStorage.removeItem(STORAGE_KEY);
   150	    }
   151	  }
   152	}
   153	
   154	/**
   155	 * Lets a route open only while the booking in progress is unpaid, belongs to the screening in
   156	 * the `id` parameter and holds at least one seat; otherwise redirects to `/`.
   157	 */
   158	export const bookingInProgressGuard: CanActivateFn = (route) => {
   159	  const booking = inject(BookingStore).booking();
   160	  const allowed =
   161	    booking !== null &&
   162	    booking.paidEmail === null &&
   163	    booking.screeningId === Number(route.paramMap.get('id')) &&
   164	    booking.items.length > 0;
   165	  return allowed || inject(Router).createUrlTree(['/']);
   166	};
   167	
   168	/** Lets a route open only once the booking is paid; otherwise redirects to `/` (spec 3.1). */
   169	export const bookingPaidGuard: CanActivateFn = () => {
   170	  const booking = inject(BookingStore).booking();
   171	  return (booking !== null && booking.paidEmail !== null) || inject(Router).createUrlTree(['/']);
   172	};
