    15	
    16	@Component({
    17	  selector: 'app-movie-list',
    18	  imports: [MatButtonModule, MatDatepickerModule, MatFormFieldModule, MatInputModule],
    19	  templateUrl: './movie-list.html',
    20	  styleUrl: './movie-list.scss',
    21	})
    22	export class MovieList {
    23	  private readonly api = inject(CinemaApi);
    24	  private readonly router = inject(Router);
    25	
    26	  /** Bound from the `date` query parameter. */
    27	  readonly date = input<string>();
    28	
    29	  private readonly now = new Date();
    30	  private readonly today = toIsoDate(this.now);
    31	
    32	  protected readonly minDate = new Date(this.now.getFullYear(), this.now.getMonth(), this.now.getDate());
    33	
    34	  protected readonly dayButtons = Array.from({ length: 5 }, (_, offset) => {
    35	    const day = new Date(this.now.getFullYear(), this.now.getMonth(), this.now.getDate() + offset);
    36	    return { iso: toIsoDate(day), label: offset === 0 ? 'Today' : WEEKDAYS[day.getDay()] };
    37	  });
    38	
    39	  /** The requested date when it is a valid ISO date and not in the past; otherwise today. */
    40	  protected readonly selectedDate = computed(() => {
    41	    const requested = this.date() ?? '';
    42	    return parseIsoDate(requested) !== null && requested >= this.today ? requested : this.today;
    43	  });
    44	
    45	  /** The datepicker shows the selected day only when no day button represents it. */
    46	  protected readonly pickerValue = computed(() => {
    47	    const selected = this.selectedDate();
    48	    return this.dayButtons.some((day) => day.iso === selected) ? null : parseIsoDate(selected);
    49	  });
    50	
    51	  protected readonly cards = resource({
    52	    params: () => this.selectedDate(),
    53	    loader: async ({ params: date }): Promise<MovieCard[]> => {
    54	      const [movies, screenings] = await Promise.all([this.api.getMovies(), this.api.getScreeningsOn(date)]);
    55	      return movies
    56	        .map((movie) => ({
    57	          movie,
    58	          screenings: screenings
    59	            .filter((screening) => screening.movieId === movie.id)
    60	            .sort((a, b) => a.time.localeCompare(b.time)),
    61	        }))
    62	        .filter((card) => card.screenings.length > 0);
    63	    },
    64	  });
    65	
    66	  protected selectDay(iso: string): void {
    67	    if (iso < this.today) {
    68	      return;
    69	    }
    70	    this.router.navigate([], { queryParams: { date: iso } });
    71	  }
    72	
    73	  protected onDatePicked(date: Date | null): void {
    74	    if (date) {
    75	      this.selectDay(toIsoDate(date));
    76	    }
    77	  }
    78	
    79	  protected openScreening(id: number): void {
    80	    this.router.navigate(['/screenings', id, 'seats']);
    81	  }
    82	}
