    10	
    11	const ROW_NUMBERS = Array.from({ length: 15 }, (_, index) => index + 1);
    12	/** Rows 1 to 10 have no seats in columns 1 to 4; that space is the entrance. */
    13	const LAST_ENTRANCE_ROW = 10;
    14	/** Row 15 is made of couches only. */
    15	const COUCH_ROW = 15;
    16	const ACCESSIBLE_ROW = 1;
    17	const ACCESSIBLE_FIRST_COLUMN = 10;
    18	const ACCESSIBLE_LAST_COLUMN = 15;
    19	/** A booking holds at most this many seats; a couch counts as two. */
    20	const MAX_SEATS = 10;
    21	
    22	export type SeatState = 'available' | 'unavailable' | 'accessible';
    23	type DisplayState = SeatState | 'selected';
    24	
    25	type Slot =
    26	  | { kind: 'seat'; key: string; row: number; column: number; state: SeatState }
    27	  | { kind: 'couch'; key: string; row: number; start: number; end: number; state: SeatState }
    28	  | { kind: 'aisle'; key: string; row: number }
    29	  | { kind: 'entrance'; key: string };
    30	
    31	/** A seat or a couch: the elements that can be selected. */
    32	type Bookable = Extract<Slot, { state: SeatState }>;
    33	
    34	interface SeatMapRow {
    35	  number: number;
    36	  slots: Slot[];
    37	}
    38	
    39	interface SeatMapData {
    40	  movie: Movie;
    41	  screening: Screening;
    42	  showDate: string;
    43	}
    44	
    45	interface SelectedRow {
    46	  row: number;
    47	  seats: string;
    48	}
    49	
    50	const LEGEND: { state: DisplayState; label: string }[] = [
    51	  { state: 'available', label: 'Available' },
    52	  { state: 'selected', label: 'Selected' },
    53	  { state: 'unavailable', label: 'Unavailable' },
    54	  { state: 'accessible', label: 'Accessible' },
    55	];
    56	
    57	function seatId(row: number, column: number): string {
    58	  return `R${row}C${column}`;
    59	}
    60	
    61	function seatState(row: number, column: number, occupied: Set<string>): SeatState {
    62	  if (occupied.has(seatId(row, column))) {
    63	    return 'unavailable';
    64	  }
    65	  const accessible =
    66	    row === ACCESSIBLE_ROW && column >= ACCESSIBLE_FIRST_COLUMN && column <= ACCESSIBLE_LAST_COLUMN;
    67	  return accessible ? 'accessible' : 'available';
    68	}
    69	
    70	/** Slots for the columns `from`..`to` of a row: single seats, or couches of two columns in row 15. */
    71	function segment(row: number, from: number, to: number, occupied: Set<string>): Slot[] {
    72	  const slots: Slot[] = [];
    73	  if (row === COUCH_ROW) {
    74	    for (let start = from; start <= to; start += 2) {
    75	      const end = start + 1;
    76	      const unavailable = occupied.has(seatId(row, start)) || occupied.has(seatId(row, end));
    77	      slots.push({
    78	        kind: 'couch',
    79	        key: `couch-${row}-${start}`,
    80	        row,
    81	        start,
    82	        end,
    83	        state: unavailable ? 'unavailable' : 'available',
    84	      });
    85	    }
    86	    return slots;
    87	  }
    88	  for (let column = from; column <= to; column++) {
    89	    slots.push({
    90	      kind: 'seat',
    91	      key: `seat-${row}-${column}`,
    92	      row,
    93	      column,
    94	      state: seatState(row, column, occupied),
    95	    });
    96	  }
    97	  return slots;
    98	}
    99	
   100	function aisle(row: number, after: number): Slot {
   101	  return { kind: 'aisle', key: `aisle-${row}-${after}`, row };
   102	}
   103	
   104	function buildRow(row: number, occupied: Set<string>): Slot[] {
   105	  const left: Slot[] =
   106	    row <= LAST_ENTRANCE_ROW
   107	      ? [{ kind: 'entrance', key: `entrance-${row}` }]
   108	      : segment(row, 1, 4, occupied);
   109	  return [
   110	    ...left,
   111	    aisle(row, 4),
   112	    ...segment(row, 5, 20, occupied),
   113	    aisle(row, 20),
   114	    ...segment(row, 21, 24, occupied),
   115	  ];
   116	}
   117	
   118	function isBookable(slot: Slot): slot is Bookable {
   119	  return slot.kind === 'seat' || slot.kind === 'couch';
   120	}
   121	
   122	/** Seats taken by an element: a couch is two seats. */
   123	function seatsIn(slot: Bookable): number {
   124	  return slot.kind === 'couch' ? 2 : 1;
   125	}
   126	
   127	function toBookedItem(slot: Bookable): BookedItem {
   128	  return slot.kind === 'couch'
   129	    ? { row: slot.row, column: slot.start, couch: true }
   130	    : { row: slot.row, column: slot.column, couch: false };
   131	}
