   145	
   146	  /** Bound from the `id` route parameter. */
   147	  readonly id = input.required<string>();
   148	
   149	  protected readonly legend = LEGEND;
   150	
   151	  /** Keys of the selected seats and couches, taken from the booking in progress. */
   152	  private readonly selection = computed<ReadonlySet<string>>(
   153	    () => new Set((this.bookings.booking()?.items ?? []).map(itemKey)),
   154	  );
   155	
   156	  protected readonly data = resource({
   157	    params: () => this.id(),
   158	    loader: async ({ params: id }): Promise<SeatMapData> => {
   159	      const screening = await this.api.getScreening(Number(id));
   160	      const movie = await this.api.getMovie(screening.movieId);
   161	      this.bookings.open(screening.id);
   162	      return { movie, screening, showDate: formatShowDate(screening.date, screening.time) };
   163	    },
   164	  });
   165	
   166	  protected readonly rows = computed<SeatMapRow[]>(() => {
   167	    const data = this.data.value();
   168	    if (!data) {
   169	      return [];
   170	    }
   171	    const occupied = new Set(data.screening.occupiedSeats);
   172	    return ROW_NUMBERS.map((number) => ({ number, slots: buildRow(number, occupied) }));
   173	  });
   174	
   175	  /** Selected elements in ascending row, then column order. */
   176	  private readonly selectedSlots = computed<Bookable[]>(() => {
   177	    const keys = this.selection();
   178	    return this.rows()
   179	      .flatMap((row) => row.slots)
   180	      .filter(isBookable)
   181	      .filter((slot) => keys.has(slot.key));
   182	  });
   183	
   184	  protected readonly selectedCount = computed(() =>
   185	    this.selectedSlots().reduce((total, slot) => total + seatsIn(slot), 0),
   186	  );
   187	
   188	  protected readonly selectedRows = computed<SelectedRow[]>(() => {
   189	    const labelsByRow = new Map<number, string[]>();
   190	    for (const slot of this.selectedSlots()) {
   191	      const label = slot.kind === 'couch' ? `${slot.start}-${slot.end}` : `${slot.column}`;
   192	      labelsByRow.set(slot.row, [...(labelsByRow.get(slot.row) ?? []), label]);
   193	    }
   194	    return [...labelsByRow].map(([row, labels]) => ({ row, seats: labels.join(', ') }));
   195	  });
   196	
   197	  constructor() {
   198	    effect(() => {
   199	      if (this.data.error()) {
   200	        this.router.navigate(['/']);
   201	      }
   202	    });
   203	    effect(() => {
   204	      const movie = this.data.value()?.movie;
   205	      if (movie) {
   206	        this.title.setTitle(`${movie.title} - Cinescope`);
   207	      }
   208	    });
   209	  }
   210	
   211	  /** The state a seat or couch is painted with: selected overrides its own state. */
   212	  protected displayState(slot: Bookable): DisplayState {
   213	    return this.selection().has(slot.key) ? 'selected' : slot.state;
   214	  }
   215	
   216	  protected toggle(slot: Bookable): void {
   217	    if (slot.state === 'unavailable') {
   218	      return;
   219	    }
   220	    const items = this.bookings.booking()?.items ?? [];
   221	    if (this.selection().has(slot.key)) {
   222	      this.bookings.setItems(items.filter((item) => itemKey(item) !== slot.key));
   223	      return;
   224	    }
   225	    if (this.selectedCount() + seatsIn(slot) > MAX_SEATS) {
   226	      this.toast.show(`Maximum ${MAX_SEATS} seats per booking`);
   227	      return;
   228	    }
   229	    this.bookings.setItems([...items, toBookedItem(slot)]);
   230	  }
   231	
   232	  protected cancel(): void {
   233	    this.bookings.clear();
   234	    this.router.navigate(['/']);
   235	  }
   236	
   237	  protected continueToSummary(): void {
   238	    if (this.selectedCount() > 0) {
   239	      this.router.navigate(['/screenings', this.id(), 'summary']);
   240	    }
   241	  }
   242	}
