    18	/** The message of each field whose rule fails; a field has at most one. */
    19	export type FieldErrors = Partial<Record<Field, string>>;
    20	
    21	/** One or more characters without spaces or `@`, `@`, then a domain with a dot inside. */
    22	const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    23	const PHONE = /^\d{9}$/;
    24	
    25	function nameError(value: string, label: string): string | undefined {
    26	  if (value === '') {
    27	    return `${label} is required`;
    28	  }
    29	  if (value.length < 2) {
    30	    return `${label} must be at least 2 characters`;
    31	  }
    32	  return undefined;
    33	}
    34	
    35	/** Validates the checkout form as typed; values are not trimmed. */
    36	export function validateCheckout(values: CheckoutValues): FieldErrors {
    37	  const errors: FieldErrors = {};
    38	
    39	  const firstName = nameError(values.firstName, 'First name');
    40	  if (firstName) {
    41	    errors.firstName = firstName;
    42	  }
    43	  const lastName = nameError(values.lastName, 'Last name');
    44	  if (lastName) {
    45	    errors.lastName = lastName;
    46	  }
    47	
    48	  if (values.email === '') {
    49	    errors.email = 'Email is required';
    50	  } else if (!EMAIL.test(values.email)) {
    51	    errors.email = 'Enter a valid email address';
    52	  }
    53	
    54	  if (values.confirmEmail === '') {
    55	    errors.confirmEmail = 'Confirm email is required';
    56	  } else if (values.confirmEmail !== values.email) {
    57	    errors.confirmEmail = 'Email addresses do not match';
    58	  }
    59	
    60	  if (values.phone !== '' && !PHONE.test(values.phone)) {
    61	    errors.phone = 'Phone number must be exactly 9 digits';
    62	  }
    63	
    64	  if (!values.terms) {
    65	    errors.terms = 'You must accept the terms and conditions';
    66	  }
    67	
    68	  return errors;
    69	}
