    19	@Component({
    20	  selector: 'app-checkout',
    21	  imports: [MatButtonModule, MatCheckboxModule, MatFormFieldModule, MatInputModule],
    22	  templateUrl: './checkout.html',
    23	  styleUrl: './checkout.scss',
    24	})
    25	export class Checkout {
    26	  private readonly api = inject(CinemaApi);
    27	  private readonly bookings = inject(BookingStore);
    28	  private readonly router = inject(Router);
    29	  private readonly toast = inject(Toast);
    30	
    31	  /** Bound from the `id` route parameter. */
    32	  readonly id = input.required<string>();
    33	
    34	  /** The values typed so far; they live in the booking, so they survive navigation and reloads. */
    35	  protected readonly form = computed<CheckoutValues>(
    36	    () => this.bookings.booking()?.form ?? emptyCheckoutValues(),
    37	  );
    38	
    39	  protected readonly total = computed(() => totalPrice(this.bookings.booking()?.items ?? []));
    40	
    41	  protected readonly payLabel = computed(() => `Pay ${formatPrice(this.total())}`);
    42	
    43	  private readonly errors = computed<FieldErrors>(() => validateCheckout(this.form()));
    44	
    45	  /** Fields the customer has left; a message is shown only for these. */
    46	  private readonly touched = signal<ReadonlySet<Field>>(new Set());
    47	
    48	  /** True while the payment request is in flight. */
    49	  protected readonly pending = signal(false);
    50	
    51	  /** The message to show under a field, if it has been left and its rule fails. */
    52	  protected error(field: Field): string | undefined {
    53	    return this.touched().has(field) ? this.errors()[field] : undefined;
    54	  }
    55	
    56	  protected touch(field: Field): void {
    57	    this.touched.update((fields) => new Set(fields).add(field));
    58	  }
    59	
    60	  protected setText(field: TextField, event: Event): void {
    61	    this.bookings.updateForm(field, (event.target as HTMLInputElement).value);
    62	  }
    63	
    64	  protected setTerms(accepted: boolean): void {
    65	    this.bookings.updateForm('terms', accepted);
    66	    this.touch('terms');
    67	  }
    68	
    69	  protected back(): void {
    70	    this.router.navigate(['/screenings', this.id(), 'summary']);
    71	  }
    72	
    73	  /** Sends the reservation; on success the booking is paid and the confirmation opens. */
    74	  protected async pay(): Promise<void> {
    75	    const booking = this.bookings.booking();
    76	    if (!booking) {
    77	      return;
    78	    }
    79	    if (Object.keys(this.errors()).length > 0) {
    80	      this.touched.set(new Set(FIELDS));
    81	      this.toast.show('The form contains errors');
    82	      return;
    83	    }
    84	
    85	    const values = this.form();
    86	    this.pending.set(true);
    87	    try {
    88	      await this.api.createReservation({
    89	        screeningId: booking.screeningId,
    90	        seats: booking.items.flatMap(seatIdentifiers),
    91	        customer: {
    92	          firstName: values.firstName,
    93	          lastName: values.lastName,
    94	          email: values.email,
    95	          phone: values.phone,
    96	        },
    97	        totalPrice: this.total(),
    98	      });
    99	    } catch {
   100	      this.pending.set(false);
   101	      this.toast.show('Payment failed. Please try again.');
   102	      return;
   103	    }
   104	    this.bookings.markPaid(values.email);
   105	    this.router.navigate(['/confirmation']);
   106	  }
   107	}
