import { chromium } from '/opt/e2e-deps/node_modules/@playwright/test/index.mjs';

const BASE = 'http://localhost:4200';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const errors = [];
page.on('pageerror', (e) => errors.push(String(e)));
page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
const log = (...a) => console.log(...a);
const tid = (id) => page.getByTestId(id);

// 1. Movie list
await page.goto(BASE + '/');
await page.waitForSelector('[data-testid="movie-card"], [data-testid="movies-empty"], [data-testid="movies-error"]');
log('URL', page.url());
const dayButtons = await page.$$eval('[data-testid="day-button"]', (els) => els.map((e) => [e.textContent.trim(), e.dataset.date, e.dataset.selected]));
log('DAYS', JSON.stringify(dayButtons));
log('DATEPICKER', await tid('date-picker').count());
const cards = await page.$$eval('[data-testid="movie-card"]', (els) => els.map((c) => ({
  id: c.dataset.movieId,
  title: c.querySelector('[data-testid="movie-title"]')?.textContent.trim(),
  genre: c.querySelector('[data-testid="movie-genre"]')?.textContent.trim(),
  runtime: c.querySelector('[data-testid="movie-runtime"]')?.textContent.trim(),
  format: c.querySelector('[data-testid="movie-format"]')?.textContent.trim(),
  screenings: [...c.querySelectorAll('[data-testid="screening-button"]')].map((b) => b.textContent.trim() + '#' + b.dataset.screeningId),
})));
log('CARDS', JSON.stringify(cards));

// Choose another date via URL and check empty state
await page.goto(BASE + '/?date=2026-12-31');
await page.waitForSelector('[data-testid="movies-empty"], [data-testid="movie-card"]');
log('FAR DATE empty?', await tid('movies-empty').count(), 'cards', await tid('movie-card').count(), 'selected', await page.$$eval('[data-testid="day-button"]', (els) => els.map((e) => e.dataset.selected).join(',')));
log('FAR DATE URL', page.url());
await page.goto(BASE + '/?date=not-a-date');
await page.waitForSelector('[data-testid="day-button"]');
await page.waitForTimeout(300);
log('INVALID date selects', await page.$$eval('[data-testid="day-button"]', (els) => els.find((e) => e.dataset.selected === 'true')?.dataset.date));

// 2. Seat map: first screening button
await page.goto(BASE + '/');
await page.waitForSelector('[data-testid="screening-button"]');
const firstScreening = await page.$eval('[data-testid="screening-button"]', (b) => b.dataset.screeningId);
await page.locator('[data-testid="screening-button"]').first().click();
await page.waitForURL(new RegExp(`/screenings/${firstScreening}/seats`));
await page.waitForSelector('[data-testid="seat-map"]');
log('SEAT TITLE', await tid('seat-map-title').textContent(), '|', await tid('seat-map-subtitle').textContent(), '|', await tid('seat-limit-info').textContent());
const counts = await page.evaluate(() => ({
  rows: document.querySelectorAll('[data-testid="seat-row"]').length,
  seats: document.querySelectorAll('[data-testid="seat"]').length,
  couches: document.querySelectorAll('[data-testid="couch"]').length,
  aisles: document.querySelectorAll('[data-testid="aisle"]').length,
  states: [...document.querySelectorAll('[data-testid="seat"],[data-testid="couch"]')].reduce((acc, e) => { const s = e.dataset.state; acc[s] = (acc[s] || 0) + 1; return acc; }, {}),
  row1: [...document.querySelectorAll('[data-testid="seat-row"][data-row="1"] [data-testid="seat"]')].map((e) => e.dataset.column + ':' + e.dataset.state).join(' '),
  row15: [...document.querySelectorAll('[data-testid="couch"][data-row="15"]')].map((e) => e.dataset.columnStart + '-' + e.dataset.columnEnd + ':' + e.dataset.state + ':' + e.textContent.trim()).join(' '),
  row1Labels: document.querySelectorAll('[data-testid="row-label-left"]').length + '/' + document.querySelectorAll('[data-testid="row-label-right"]').length,
  row5first: document.querySelector('[data-testid="seat-row"][data-row="5"] [data-testid="seat"]')?.dataset.column,
  row10first: document.querySelector('[data-testid="seat-row"][data-row="10"] [data-testid="seat"]')?.dataset.column,
  row11first: document.querySelector('[data-testid="seat-row"][data-row="11"] [data-testid="seat"]')?.dataset.column,
  legend: [...document.querySelectorAll('[data-testid="legend-item"]')].map((e) => e.textContent.trim() + '=' + e.dataset.state + '=' + getComputedStyle(e.querySelector('.swatch')).backgroundColor),
  colours: [...new Set([...document.querySelectorAll('[data-testid="seat"],[data-testid="couch"]')].map((e) => e.dataset.state + '=' + getComputedStyle(e).backgroundColor))],
  aisleWidth: document.querySelector('[data-testid="aisle"]')?.getBoundingClientRect().width,
  seatWidth: document.querySelector('[data-testid="seat"]')?.getBoundingClientRect().width,
  couchWidth: document.querySelector('[data-testid="couch"]')?.getBoundingClientRect().width,
  screenAboveRow1: document.querySelector('[data-testid="screen-indicator"]').getBoundingClientRect().bottom <= document.querySelector('[data-testid="seat-row"][data-row="1"]').getBoundingClientRect().top,
}));
log('SEATMAP', JSON.stringify(counts, null, 1));
log('SELECTED PANEL', await tid('selected-seats-count').textContent(), '| continue disabled', await tid('continue-button').isDisabled());

// Pick: row 7 seats 12, 13 ; row 15 couch 1-2 ; then row 1 accessible col 10
const pick = async (sel) => page.locator(sel).first().click();
await page.locator('[data-testid="seat"][data-row="7"][data-column="12"]').click();
await page.locator('[data-testid="seat"][data-row="7"][data-column="13"]').click();
await page.locator('[data-testid="couch"][data-row="15"][data-column-start="1"]').click();
await page.locator('[data-testid="seat"][data-row="1"][data-column="10"]').click();
log('PANEL', await tid('selected-seats-count').textContent(), JSON.stringify(await page.$$eval('[data-testid="selected-seats-row"]', (els) => els.map((e) => e.textContent.trim()))));
log('SELECTED STATE', await page.locator('[data-testid="seat"][data-row="1"][data-column="10"]').getAttribute('data-state'));
// deselect the accessible one
await page.locator('[data-testid="seat"][data-row="1"][data-column="10"]').click();
log('AFTER DESELECT', await tid('selected-seats-count').textContent());

// Cap at 10: currently 5 seats (7-12, 7-13, couch 2). Add row 6 seats 1..? seat map row 6 starts col 5
for (const c of [5, 6, 7, 8, 9]) await page.locator(`[data-testid="seat"][data-row="6"][data-column="${c}"]`).click();
log('AT CAP', await tid('selected-seats-count').textContent());
await page.locator('[data-testid="seat"][data-row="6"][data-column="10"]').click();
await page.waitForTimeout(200);
log('OVER CAP toast', await tid('toast').count(), (await tid('toast').allTextContents()).join('|'), 'count', await tid('selected-seats-count').textContent());
await page.waitForTimeout(4500);
log('TOAST gone after 4.5s', await tid('toast').count());
log('CAP PANEL', JSON.stringify(await page.$$eval('[data-testid="selected-seats-row"]', (els) => els.map((e) => e.textContent.trim()))));
// deselect couch allowed at cap
await page.locator('[data-testid="couch"][data-row="15"][data-column-start="1"]').click();
log('AFTER COUCH DESELECT', await tid('selected-seats-count').textContent());
await page.locator('[data-testid="couch"][data-row="15"][data-column-start="1"]').click();
log('AFTER COUCH REselect', await tid('selected-seats-count').textContent());

// 3. Summary
await tid('continue-button').click();
await page.waitForURL(new RegExp(`/screenings/${firstScreening}/summary`));
log('SUMMARY title', await tid('summary-title').textContent());
const items = await page.$$eval('[data-testid="summary-item"]', (els) => els.map((e) => ['title', 'datetime', 'row', 'seat', 'price'].map((k) => e.querySelector(`[data-testid="summary-item-${k}"]`)?.textContent.trim()).join(' | ')));
log('ITEMS', JSON.stringify(items, null, 1));
log('TOTAL', await tid('summary-total').textContent());
await tid('back-button').click();
await page.waitForURL(new RegExp(`/screenings/${firstScreening}/seats`));
log('BACK keeps', await tid('selected-seats-count').textContent());
await tid('continue-button').click();
await page.waitForURL(/summary/);
await tid('confirm-button').click();
await page.waitForURL(/checkout/);
log('CHECKOUT title', await tid('checkout-title').textContent(), 'pay', await tid('pay-button').textContent());

// 4. Checkout validation
await tid('first-name-input').fill('A');
await tid('first-name-input').blur();
await tid('email-input').fill('not-an-email');
await tid('email-input').blur();
await tid('phone-input').fill('12345');
await tid('phone-input').blur();
await tid('confirm-email-input').fill('x@y.com');
log('ERR after typing', JSON.stringify(await page.$$eval('[data-testid$="-error"]', (els) => els.map((e) => e.dataset.testid + ': ' + e.textContent.trim()))));
await tid('pay-button').click();
await page.waitForTimeout(300);
log('ERR after pay', JSON.stringify(await page.$$eval('[data-testid$="-error"]', (els) => els.map((e) => e.dataset.testid + ': ' + e.textContent.trim()))));
log('TOAST', (await tid('toast').allTextContents()).join('|'), 'url', page.url());
log('LABELS', JSON.stringify(await page.$$eval('[data-testid$="-label"]', (els) => els.map((e) => e.textContent.trim()))));

// valid form
await tid('first-name-input').fill('Anna');
await tid('last-name-input').fill('Kowalska');
await tid('email-input').fill('anna@example.com');
await tid('confirm-email-input').fill('anna@example.com');
await tid('phone-input').fill('');
await tid('terms-checkbox').click();
log('VALID errors', await page.$$eval('[data-testid$="-error"]', (els) => els.length));
// Back and forth keeps values
await tid('checkout-back-button').click();
await page.waitForURL(/summary/);
await tid('confirm-button').click();
await page.waitForURL(/checkout/);
log('VALUES kept', await tid('first-name-input').inputValue(), await tid('terms-checkbox').locator('input').isChecked());
await page.reload();
await page.waitForSelector('[data-testid="pay-button"]');
log('VALUES after reload', await tid('email-input').inputValue(), 'pay', await tid('pay-button').textContent());

// Pay
await tid('pay-button').click();
await page.waitForURL(/confirmation/);
log('CONFIRM', await tid('confirmation-heading').textContent(), '|', await tid('confirmation-message').textContent());
await page.reload();
log('CONFIRM after reload', await tid('confirmation-message').textContent());
await tid('confirmation-continue-button').click();
await page.waitForURL(/localhost:4200\/?(\?.*)?$/);
log('AFTER CONTINUE url', page.url());
await page.goto(BASE + `/screenings/${firstScreening}/seats`);
await page.waitForSelector('[data-testid="seat-map"]');
log('NEW BOOKING count', await tid('selected-seats-count').textContent());
await page.goto(BASE + '/confirmation');
await page.waitForTimeout(500);
log('GUARD confirmation url', page.url());
await page.goto(BASE + '/nope');
await page.waitForTimeout(500);
log('UNKNOWN url', page.url());
log('PAGE ERRORS', JSON.stringify(errors));
await browser.close();

