import { chromium } from '/opt/e2e-deps/node_modules/@playwright/test/index.mjs';

const BASE = 'http://localhost:4200';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const errors = [];
page.on('pageerror', (e) => errors.push(String(e)));
const log = (...a) => console.log(...a);
const tid = (id) => page.getByTestId(id);
const settle = () => page.waitForTimeout(150);

// Datepicker shows a date outside the five buttons
await page.goto(BASE + '/?date=2026-12-05');
await page.waitForSelector('[data-testid="day-picker"]');
await settle();
log('PICKER value for 12-05', await tid('date-picker').inputValue(), 'selected', await page.$$eval('[data-testid="day-button"]', (els) => els.map((e) => e.dataset.selected).join(',')));
log('CARDS for 12-05', await tid('movie-card').count(), await tid('movies-empty').count());

// Choosing a day button via click updates URL
await page.goto(BASE + '/');
await page.waitForSelector('[data-testid="day-button"]');
await page.locator('[data-testid="day-button"]').nth(2).click(); await settle();
log('CLICK day3 URL', page.url(), await page.$$eval('[data-testid="day-button"]', (els) => els.map((e) => e.dataset.selected).join(',')));

// Retry flow: first movie request fails
let fail = true;
await page.route('**/movies', async (route) => {
  if (fail) { fail = false; await route.abort(); } else { await route.continue(); }
});
await page.goto(BASE + '/?date=2026-11-27');
await page.waitForSelector('[data-testid="movies-error"]');
log('ERROR shown', await tid('movies-error').textContent(), 'retry', await tid('movies-retry-button').count(), 'cards', await tid('movie-card').count());
await tid('movies-retry-button').click(); await settle();
await page.waitForSelector('[data-testid="movie-card"]');
log('RETRY ok cards', await tid('movie-card').count(), 'error gone', await tid('movies-error').count());
await page.unroute('**/movies');

// Loading indicator while in flight
await page.route('**/screenings?**', async (route) => { await new Promise((r) => setTimeout(r, 1200)); await route.continue(); });
await page.goto(BASE + '/?date=2026-11-27');
await settle();
log('LOADING shown', await tid('movies-loading').count(), 'cards', await tid('movie-card').count());
await page.waitForSelector('[data-testid="movie-card"]', { timeout: 5000 });
log('LOADING gone', await tid('movies-loading').count());
await page.unroute('**/screenings?**');

// 404 seat map -> redirect to /
await page.goto(BASE + '/screenings/999/seats');
await page.waitForTimeout(800);
log('404 redirect', page.url());

// Summary without booking -> /
await page.goto(BASE + '/screenings/1/summary');
await page.waitForTimeout(800);
log('summary no booking', page.url());

// Cancel clears selection; Remove last item; summary guard
await page.goto(BASE + '/');
await page.waitForSelector('[data-testid="screening-button"]');
await page.locator('[data-testid="screening-button"]').first().click();
await page.waitForSelector('[data-testid="seat-map"]');
const sid = page.url().match(/screenings\/(\d+)/)[1];
await page.locator('[data-testid="seat"][data-row="7"][data-column="12"]').click(); await settle();
log('SEL before cancel', await tid('selected-seats-count').textContent());
await tid('cancel-button').click(); await settle();
log('CANCEL url', page.url());
await page.goto(BASE + `/screenings/${sid}/seats`);
await page.waitForSelector('[data-testid="seat-map"]');
log('after cancel count', await tid('selected-seats-count').textContent());
await page.locator('[data-testid="seat"][data-row="7"][data-column="12"]').click(); await settle();
await tid('continue-button').click();
await page.waitForSelector('[data-testid="summary-item"]');
await tid('summary-item-remove-button').click(); await settle();
log('REMOVE last url', page.url());
await page.goto(BASE + `/screenings/${sid}/summary`);
await page.waitForTimeout(800);
log('summary after clear url', page.url());
log('PAGE ERRORS', JSON.stringify(errors));
await browser.close();

